async function u(c=1){const o=`${window.APP_CONFIG?.baseUrl||"/"}api/regions?country_id=${c}`;try{const i=await(await fetch(o)).json();return i.success?i.data.map(t=>({id:t.id,name:t.region})):[]}catch(e){return console.error("Fetch Regions Error:",e),[]}}function g(c){const n=document.getElementById(c);if(!n)return;const o=n.querySelector('select[name="countryId"]')||n.querySelector('select[name="country_id"]'),e=n.querySelector('select[name="regionId"]')||n.querySelector('select[name="region_id"]');!o||!e||o.addEventListener("change",async i=>{const t=o.value,a=i.detail?.preSelectedRegionId;if(!a){const r=n.querySelector('input[name="city"]');r&&(r.value="")}if(!t){e.innerHTML='<option value="">Select Region</option>';return}e.innerHTML='<option value="">Loading...</option>',e.disabled=!0;try{const l=(await u(t)).map(s=>{const d=a&&String(s.id)===String(a);return`<option value="${s.id}" ${d?"selected":""}>${s.name}</option>`}).join("");e.innerHTML=`
                <option value="">Select Region</option>
                ${l}
            `}catch(r){console.error("Failed to reload regions:",r),e.innerHTML='<option value="">Error loading regions</option>'}finally{e.disabled=!1}})}export{g as e,u as f};
